from decimal import Decimal

from src.billing.tax import invoice_tax, line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_uses_bankers_rounding():
    assert tax_for(25, Decimal("0.1")) == 2  # 2.5 -> 2 (half to even)
    assert tax_for(35, Decimal("0.1")) == 4  # 3.5 -> 4 (half to even)


def test_tax_for_accepts_float_rate():
    assert tax_for(1000, 0.07) == 70


def test_invoice_tax_rounds_per_line():
    lines = [
        {"quantity": 1, "unit_cents": 13},
        {"quantity": 1, "unit_cents": 13},
    ]
    # Each line: 1.3 -> 1, summed = 2. Rounding the total (2.6) would give 3.
    assert invoice_tax(lines, Decimal("0.1")) == 2


def test_invoice_tax_uses_line_quantity():
    lines = [{"quantity": 3, "unit_cents": 250}]
    assert invoice_tax(lines, Decimal("0.08")) == 60


def test_invoice_tax_empty():
    assert invoice_tax([], Decimal("0.1")) == 0

